package com.adria.transaction.web.graphql;import com.adria.transaction.domain.BankTransaction;import com.adria.transaction.service.TransactionService;import org.springframework.graphql.data.method.annotation.*;import org.springframework.stereotype.Controller;import java.util.*;@Controller public class TransactionGraphQLController{private final TransactionService service;public TransactionGraphQLController(TransactionService s){service=s;}@QueryMapping public List<BankTransaction> transactions(){return service.all();}@QueryMapping public BankTransaction transactionById(@Argument UUID id){return service.get(id);}}